BEGIN;

-- ────────────────────────────────────────────────────────────
-- SCHEMA
-- ────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS publishers (
    publisher_id   SERIAL       PRIMARY KEY,
    name           TEXT         NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS series (
    series_id      SERIAL       PRIMARY KEY,
    title          TEXT         NOT NULL,
    publisher_id   INTEGER      NOT NULL
                                REFERENCES publishers(publisher_id),
    UNIQUE (title, publisher_id)
);

CREATE TABLE IF NOT EXISTS volumes (
    volume_id      SERIAL       PRIMARY KEY,
    series_id      INTEGER      NOT NULL
                                REFERENCES series(series_id),
    volume_number  INTEGER      NOT NULL DEFAULT 1,
    UNIQUE (series_id, volume_number)
);

CREATE TABLE IF NOT EXISTS issues (
    issue_id            SERIAL   PRIMARY KEY,
    volume_id           INTEGER  NOT NULL
                                 REFERENCES volumes(volume_id),
    issue_number        TEXT,
    story_title         TEXT,
    variant_description TEXT,
    release_date        DATE,
    format              TEXT,
    creators            TEXT
);

CREATE TABLE IF NOT EXISTS personal_collections (
    collection_id        SERIAL      PRIMARY KEY,
    user_id              INTEGER     NOT NULL,
    issue_id             INTEGER     NOT NULL
                                     REFERENCES issues(issue_id),
    added_date           DATE,
    grade                SMALLINT    CHECK (grade IS NULL OR grade BETWEEN 1 AND 10),
    slabbed              BOOLEAN     NOT NULL DEFAULT FALSE,
    value_override       NUMERIC(10,2),
    description          TEXT,
    principal_characters TEXT,
    CONSTRAINT slabbed_requires_grade CHECK (slabbed = FALSE OR grade IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS comics (
    comic_id       SERIAL   PRIMARY KEY,
    issue_id       INTEGER  NOT NULL UNIQUE
                            REFERENCES issues(issue_id),
    publisher_id   INTEGER  NOT NULL
                            REFERENCES publishers(publisher_id),
    series_id      INTEGER  NOT NULL
                            REFERENCES series(series_id),
    volume_id      INTEGER  NOT NULL
                            REFERENCES volumes(volume_id)
);

-- ────────────────────────────────────────────────────────────
-- Sequence resets — keep SERIAL in sync with explicit IDs
-- ────────────────────────────────────────────────────────────

SELECT setval('publishers_publisher_id_seq', 80);
SELECT setval('series_series_id_seq',        2069);
SELECT setval('volumes_volume_id_seq',       2264);
SELECT setval('issues_issue_id_seq',         14301);
SELECT setval('comics_comic_id_seq',         14301);

-- ────────────────────────────────────────────────────────────
-- publishers
-- ────────────────────────────────────────────────────────────

ON CONFLICT (publisher_id) DO NOTHING;

-- ────────────────────────────────────────────────────────────
-- series
-- ────────────────────────────────────────────────────────────

ON CONFLICT (series_id) DO NOTHING;
ON CONFLICT (series_id) DO NOTHING;
ON CONFLICT (series_id) DO NOTHING;
ON CONFLICT (series_id) DO NOTHING;
ON CONFLICT (series_id) DO NOTHING;

-- ────────────────────────────────────────────────────────────
-- volumes
-- ────────────────────────────────────────────────────────────

ON CONFLICT (volume_id) DO NOTHING;
ON CONFLICT (volume_id) DO NOTHING;
ON CONFLICT (volume_id) DO NOTHING;
ON CONFLICT (volume_id) DO NOTHING;
ON CONFLICT (volume_id) DO NOTHING;

